"""Conscious: a tiny CLI journaling assistant that finds mood patterns in entries."""
import json,sys,datetime,collections
DB="entries.json"
POS={"happy","great","good","calm","excited","proud","focused"}
NEG={"sad","tired","anxious","stressed","angry","bad","lonely"}
def load():
    try: return json.load(open(DB))
    except: return []
def score(t):
    w=t.lower().split(); return sum(x in POS for x in w)-sum(x in NEG for x in w)
def add(t):
    e=load(); e.append({"d":str(datetime.date.today()),"t":t,"s":score(t)}); json.dump(e,open(DB,"w"))
def report():
    e=load(); by=collections.defaultdict(list)
    for x in e: by[x["d"]].append(x["s"])
    for d,v in sorted(by.items()): print(d,"mood",sum(v)/len(v))
if __name__=="__main__":
    if sys.argv[1:2]==["add"]: add(" ".join(sys.argv[2:]))
    else: report()

def streak():
    ds=sorted({x["d"] for x in load()}); return len(ds)
def insights():
    e=load()
    if not e: return print("No entries yet.")
    avg=sum(x["s"] for x in e)/len(e)
    print(f"{len(e)} entries, avg mood {avg:.2f}, {streak()} active days")
    print("Reflect:", "What gave you energy today?" if avg>=0 else "What's one small thing that would help tomorrow?")
